<?php
declare(strict_types=1);
namespace WexaShelf;
use PDO;
/** Owner account security. Secret material never enters catalog backups. */
final class AccountSecurity {
 public function __construct(private PDO $db,private Repository $repo,private array $config,private ?Auth $auth=null){}
 public function raw():array{return $this->repo->setting('account-security',['revision'=>0,'securityRevision'=>0,'mfa'=>null,'pending'=>null]);}
 public static function base32(string $bytes):string{$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$out='';$buffer=0;$bits=0;foreach(unpack('C*',$bytes)as$byte){$buffer=($buffer<<8)|$byte;$bits+=8;while($bits>=5){$bits-=5;$out.=$alphabet[($buffer>>$bits)&31];}$buffer&=(1<<$bits)-1;}if($bits)$out.=$alphabet[($buffer<<(5-$bits))&31];return $out;}
 private static function decode(string $secret):string{if(!preg_match('/^[A-Z2-7]{16,128}$/D',$secret))throw new ApiException('Invalid authenticator secret.');$buffer=0;$bits=0;$out='';foreach(str_split($secret)as$c){$buffer=($buffer<<5)|strpos('ABCDEFGHIJKLMNOPQRSTUVWXYZ234567',$c);$bits+=5;if($bits>=8){$bits-=8;$out.=chr(($buffer>>$bits)&255);}$buffer&=(1<<$bits)-1;}return $out;}
 public static function totp(string $secret,int $time,int $digits=6):string{$counter=intdiv($time,30);$hash=hash_hmac('sha1',pack('N2',intdiv($counter,4294967296),$counter%4294967296),self::decode($secret),true);$offset=ord($hash[19])&15;$number=unpack('N',substr($hash,$offset,4))[1]&0x7fffffff;return str_pad((string)($number%(10**$digits)),$digits,'0',STR_PAD_LEFT);}
 private static function counter(string $secret,string $code,int $last):?int{if(!preg_match('/^\d{6}$/D',$code))return null;$now=intdiv(time(),30);foreach([0,-1,1]as$offset){$step=$now+$offset;if($step>$last&&hash_equals(self::totp($secret,$step*30),$code))return $step;}return null;}
 public function consumeCode(string $code):void{
  $s=$this->raw();if(!$s['mfa'])return;$step=self::counter($s['mfa']['secret'],$code,$s['mfa']['lastCounter']);if($step!==null){$s['mfa']['lastCounter']=$step;}else{$hash=hash('sha256',strtoupper(str_replace('-','',$code)));$index=array_search($hash,$s['mfa']['recoveryHashes'],true);if($index===false)throw new ApiException('Invalid credentials or verification code.',401);array_splice($s['mfa']['recoveryHashes'],$index,1);}$this->repo->setSetting('account-security',$s);
 }
 public function state():array{$s=$this->raw();$sessions=[];$q=$this->db->query('SELECT token,expires FROM ws_sessions ORDER BY expires DESC');$current=Auth::sessionId();foreach($q->fetchAll()as$row){if((int)$row['expires']<=Auth::now())continue;$p=$this->repo->setting('session-principal:'.$row['token'],['id'=>'owner','securityRevision'=>0]);if($p['id']==='owner'&&($p['securityRevision']??0)!==$s['securityRevision'])continue;if($p['id']!=='owner'){$active=false;foreach((new EditorRoles($this->repo))->users()as$user)if($user['id']===$p['id']&&$user['enabled']&&$user['revision']===($p['revision']??null))$active=true;if(!$active)continue;}$sessions[]=['id'=>$row['token'],'accountId'=>$p['id'],'createdAt'=>$p['createdAt']??null,'expires'=>(int)$row['expires'],'current'=>hash_equals($row['token'],$current)];}return ['revision'=>$s['revision'],'securityRevision'=>$s['securityRevision'],'mfaEnabled'=>$s['mfa']!==null,'recoveryCodesRemaining'=>count($s['mfa']['recoveryHashes']??[]),'pendingEnrollment'=>($s['pending']['expires']??0)>time(),'sessions'=>$sessions];}
 private function revokeAll():void{$this->db->exec('DELETE FROM ws_sessions');$this->db->exec("DELETE FROM ws_settings WHERE setting_key LIKE 'session-principal:%'");}
 private static function recovery():array{$codes=[];for($i=0;$i<10;$i++)$codes[]=strtoupper(bin2hex(random_bytes(10)));return $codes;}
 public function change(array $v):array{
  if(!$this->auth||($this->auth->principal()['role']??null)!=='owner')throw new ApiException('Owner session required.',403);
  Validation::check(is_int($v['revision']??null)&&in_array($v['action']??null,['password','totp-prepare','totp-confirm','totp-disable','recovery-regenerate','revoke','revoke-all'],true),'Invalid security action.');$this->auth->rateLimit('security:'.hash('sha256',$_SERVER['REMOTE_ADDR']??'local'),10,900000);
  return $this->repo->transaction(function()use($v){$s=$this->raw();if($s['revision']!==$v['revision'])throw new ApiException('Security settings changed. Reload.',409);$password=$v['currentPassword']??'';if(!is_string($password)||strlen($password)>256||!password_verify(hash('sha256',$password),(string)$this->repo->setting('password','')))throw new ApiException('Current password is incorrect.',401);if($s['mfa']){$this->consumeCode(is_string($v['code']??null)?$v['code']:'');$s=$this->raw();}$extra=[];$invalidate=false;
   switch($v['action']){
    case 'password':$next=$v['newPassword']??'';Validation::check(is_string($next)&&strlen($next)>=12&&strlen($next)<=256,'New password must contain 12–256 characters.');Validation::check(!hash_equals($password,$next),'Choose a different new password.');$this->repo->setSetting('password',password_hash(hash('sha256',$next),PASSWORD_DEFAULT));$invalidate=true;break;
    case 'totp-prepare':Validation::check(!$s['mfa'],'Disable the current authenticator before enrolling another.');$secret=self::base32(random_bytes(20));$s['pending']=['secret'=>$secret,'expires'=>time()+600];$extra=['enrollment'=>['secret'=>$secret,'otpauthUri'=>'otpauth://totp/'.rawurlencode('WexaShelf:owner@'.(parse_url($this->config['site']['url'],PHP_URL_HOST)?:'local')).'?secret='.$secret.'&issuer=WexaShelf&algorithm=SHA1&digits=6&period=30','expires'=>$s['pending']['expires']]];break;
    case 'totp-confirm':Validation::check(!$s['mfa']&&($s['pending']['expires']??0)>time(),'Authenticator enrollment expired. Start again.');$step=self::counter($s['pending']['secret'],is_string($v['code']??null)?$v['code']:'',-1);Validation::check($step!==null,'Authenticator code is incorrect.');$codes=self::recovery();$s['mfa']=['secret'=>$s['pending']['secret'],'lastCounter'=>$step,'recoveryHashes'=>array_map(fn($c)=>hash('sha256',$c),$codes)];$s['pending']=null;$extra=['recoveryCodes'=>$codes];$invalidate=true;break;
    case 'totp-disable':$s['mfa']=null;$s['pending']=null;$invalidate=true;break;
    case 'recovery-regenerate':Validation::check($s['mfa']!==null,'Enable an authenticator first.');$codes=self::recovery();$s['mfa']['recoveryHashes']=array_map(fn($c)=>hash('sha256',$c),$codes);$extra=['recoveryCodes'=>$codes];break;
    case 'revoke':$id=$v['sessionId']??'';Validation::check(is_string($id)&&preg_match('/^[a-f0-9]{64}$/D',$id),'Invalid session ID.');$this->db->prepare('DELETE FROM ws_sessions WHERE token=?')->execute([$id]);$this->db->prepare('DELETE FROM ws_settings WHERE setting_key=?')->execute(['session-principal:'.$id]);break;
    case 'revoke-all':$invalidate=true;break;
   }
   if($invalidate){$s['securityRevision']++;$this->revokeAll();}$s['revision']++;$this->repo->setSetting('account-security',$s);$this->repo->audit('account-security',$v['action'],'revision='.$s['revision']);return array_merge($this->state(),$extra,['reauthenticationRequired'=>$invalidate||($v['action']==='revoke'&&($v['sessionId']??'')===Auth::sessionId())]);
  });
 }
 public function recoverLocal(string $password):void{if(PHP_SAPI!=='cli')throw new ApiException('Recovery is available only through the local CLI.',403);Validation::check(strlen($password)>=12&&strlen($password)<=256,'Recovery password must contain 12–256 characters.');$this->repo->transaction(function()use($password){$s=$this->raw();$s['revision']++;$s['securityRevision']++;$s['mfa']=null;$s['pending']=null;$this->repo->setSetting('password',password_hash(hash('sha256',$password),PASSWORD_DEFAULT));$this->repo->setSetting('account-security',$s);$this->revokeAll();$this->repo->audit('owner-recovery','local-cli','All sessions revoked; MFA reset.');});}
}
